// Original practice situations; no dialogue or lyrics from a published work.
// Pipes mark meaningful Japanese phrase boundaries, never displayed text.
const item = (text, meaning, answerParts, answerMeaning, prompt, learnNote, others, hint, words, transfer, acceptedOrders) => ({
  text: text.replaceAll('|', ''),
  phrases: text.split('|'),
  meaning, answer: answerParts.join(''), answerParts, answerMeaning,
  prompt, learnNote, others, hint, words, transfer, ...(acceptedOrders ? {acceptedOrders} : {}),
});
const transfer = (prompt, answer, others, explanation, position) => {
  const options = [...others];
  options.splice(position, 0, answer);
  return {prompt, options, answer: position, explanation};
};
const lesson = (partner, scene, activity, items, image) => ({
  mode: 'course-expansion', partner, scene, activity, items, ...(image ? {image} : {}),
});

