// Fixed per-lesson schedules keep transfer positions independent of the main quiz.
// Either complete sentence can lead when correcting the same misunderstanding.
for (const [direction, index, alternate] of [
 ['ko-ja', 0, [3, 0, 1, 2]],
 ['ja-ko', 0, [2, 0, 1]],
 ['ko-ja', 2, [3, 4, 0, 1, 2]],
 ['ja-ko', 2, [2, 0, 1]],
]) {
 const entry = courseFourContent[direction]['course4-11'].items[index];
 entry.acceptedOrders = [entry.answerParts.map((_, i) => i), alternate];
}

const transferAnswerPositions = {
 'ko-ja': {
  'course4-8': [1, 2, 0],
  'course4-9': [2, 0, 1],
  'course4-10': [0, 2, 1],
  'course4-11': [1, 0, 2],
  'course4-12': [2, 1, 0],
  'course4-13': [0, 1, 2],
  'course4-14': [2, 0, 1],
  'course4-15': [1, 2, 0],
  'course4-16': [0, 2, 1],
  'course4-17': [2, 1, 0],
 },
 'ja-ko': {
  'course4-8': [2, 1, 0],
  'course4-9': [0, 2, 1],
  'course4-10': [1, 0, 2],
  'course4-11': [2, 0, 1],
  'course4-12': [1, 2, 0],
  'course4-13': [0, 1, 2],
  'course4-14': [1, 0, 2],
  'course4-15': [2, 1, 0],
  'course4-16': [0, 2, 1],
  'course4-17': [1, 2, 0],
 },
};
for (const [direction, lessons] of Object.entries(courseFourContent)) {
 for (const [id, content] of Object.entries(lessons)) {
  content.items.forEach((entry, index) => {
   const review = entry.transfer;
   const correct = review.options[review.answer];
   const others = review.options.filter((_, position) => position !== review.answer);
   review.answer = transferAnswerPositions[direction][id][index];
   others.splice(review.answer, 0, correct);
   review.options = others;
  });
 }
}
